package com.yeyamo_mobile.api.messaging_service.infrastructure.messaging;
import java.time.Instant;import java.util.*;import java.util.concurrent.TimeUnit;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.messaging_service.application.port.MessagingEventPort;
@Component public class KafkaWebSocketEventAdapter implements MessagingEventPort{
 private final KafkaTemplate<String,String>kafka;private final SimpMessagingTemplate websocket;private final ObjectMapper mapper;private final String topic;
 public KafkaWebSocketEventAdapter(KafkaTemplate<String,String>k,SimpMessagingTemplate w,ObjectMapper m,@Value("${yeyamo.kafka.topics.messaging-events:messaging.events}")String topic){kafka=k;websocket=w;mapper=m;this.topic=topic;}
 public void publish(String type,String aggregate,String actor,String correlation,Collection<String>recipients,Map<String,Object>payload,Object realtime){try{UUID id=UUID.randomUUID();Instant now=Instant.now();String correlationId=correlation==null?id.toString():correlation;Map<String,Object>body=new LinkedHashMap<>(payload);body.put("recipientIds",recipients);Map<String,Object>event=new LinkedHashMap<>();event.put("eventId",id);event.put("eventType",type);event.put("eventVersion",1);event.put("occurredAt",now);event.put("producer","messaging-service");event.put("aggregateType","conversation");event.put("aggregateId",aggregate);event.put("correlationId",correlationId);event.put("actorId",actor);event.put("payload",body);kafka.send(topic,aggregate,mapper.writeValueAsString(event)).get(5,TimeUnit.SECONDS);RealtimeEvent realtimeEvent=new RealtimeEvent(id,type,1,now,correlationId,realtime);for(String recipient:recipients)websocket.convertAndSendToUser(recipient,"/queue/messaging",realtimeEvent);}catch(Exception e){throw new IllegalStateException("Cannot publish messaging event",e);}}
 public record RealtimeEvent(UUID eventId,String eventType,int eventVersion,Instant occurredAt,String correlationId,Object payload){}
}
